"""Synthetic persona identities, generated by Claude. Entirely fictitious people for decoy accounts."""
from __future__ import annotations

from . import llm


async def generate_identity(s) -> dict:
    """Returns {first_name, last_name, address{street_number, street_name, city, state, zip}}."""
    data = llm.complete_json(s, (
        "Invent one entirely fictitious US bank customer for a fraud-honeypot decoy account. "
        "Return ONLY JSON: "
        '{"first_name": str, "last_name": str, "address": {"street_number": str, "street_name": str, '
        '"city": str, "state": 2-letter, "zip": 5-digit}}. '
        "Make it realistic and varied; do not use a real person."
    ), max_tokens=300)
    a = data["address"]
    return {
        "first_name": str(data["first_name"])[:80],
        "last_name": str(data["last_name"])[:80],
        "address": {
            "street_number": str(a["street_number"])[:12],
            "street_name": str(a["street_name"])[:80],
            "city": str(a["city"])[:80],
            "state": str(a["state"])[:2].upper(),
            "zip": str(a["zip"])[:5],
        },
    }
